///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // btn_MktReq.src = "../img/btn/btn_mktlist_d.gif";
        // btn_MktReq.disabled = true;

        // 여러번 수신받을수 있도록 수정  jackal 10.05.27
        // btn_MktReq.src = "../img/btn/btn_mktlist.gif";
        // btn_MktReq.disabled = false;

        // PanelToGroupBox(panel_Top);

        // fn_getDate();
        // setObjectValue(edt_SDate, dts_getDate.NameString(1, "CALND_DD"));
        if (js_market === "2") {
            scwin.mktId = 'KSQ';
        } else if (js_market === "6") {
            scwin.mktId = 'KNX';
        } else {
            scwin.mktId = 'A';
        }
        const vCurDate = $c.ut.cGetToday("yyyymmdd");
        const vCurMonth = $c.ut.cGetMinusMonth(vCurDate.substring(0, 4), vCurDate.substring(4, 6), vCurDate.substring(6, 8), 2);
        edt_BzSDate.setValue(vCurMonth);
        edt_BzEDate.setValue(vCurDate);
        $c.stf.comboCbDataSetPeriod(cmb_PeriodTp_3);
        await scwin.list();
        $c.cm.fn_com_isur_4_tab(txb_ISUR_CD_3, txb_COM_NM_3, 60, 25);
        // fn_btnSet();        // 초기 화면에 반영되로록 수정

        // fn_RefreshForm(60000);  // 이부분은 입력체크중에 refresh하면  입력데이타가 없어지니
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10700.onpageload" });
    }
};

