/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        // 엑셀 로그
        $c.stf.doLogSave("ULDSTF10700.xml", SCREN_PROCS_TP_CD_07);
        if (MaxTab_01.getSelectedTabIndex() === 1) {
            $c.data.downloadGridViewExcel(grd_List_2, {fileName: "시장조치 기준가격 미처리현황", type: "8"});
        } else if (MaxTab_01.getSelectedTabIndex() === 2) {
            $c.data.downloadGridViewExcel(grd_ListBond, {fileName: "시장조치 기준가격 처리현황", type: "8"});
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10700.btn_Excel_onclick" });
    }
};

