/**
 * @method
 * @name grd_ListBond_OnDblClick
 * @description grd_ListBond 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_ListBond_OnDblClick = async function(row, colid) {
    try {
        scwin.setContnId(row);
        if (colid === "DISCLS_PROCS_DDTM") {
            await $c.stf.openDisclViewer(scwin.gAcptNo, "R");
        } else if (colid === "ADM_YN") {
            const options = {
                id: "ULDSTF41003.gfm?IsuCd=" + scwin.gIsuCd + "&CalndDd=" + $c.stf",
                title: "시장조치시스템 수신 내역",
                type: "browserPopup",
                width: "640px",
                height: "350px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("/lstmgt/ULDSTF41003.gfm?IsuCd=" + scwin.gIsuCd + "&CalndDd=" + $c.stf.getObjectValue(edt_SDate) + "&TypeCd=1", options);
        } else if (colid === "HALT_YN") {
            const options = {
                id: "ULDSTF41003.gfm?IsuCd=" + scwin.gIsuCd + "&CalndDd=" + $c.stf",
                title: "시장조치시스템 수신 내역",
                type: "browserPopup",
                width: "640px",
                height: "350px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("/lstmgt/ULDSTF41003.gfm?IsuCd=" + scwin.gIsuCd + "&CalndDd=" + edt_SDate.getValue() + "&TypeCd=2", options);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10700.grd_ListBond_OnDblClick" });
    }
};

/**
 * @method
 * @name grd_List_1_OnClick
 * @description grd_List_1 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_1_OnClick = function(row, colid) {
    try {
        if (colid === "DISCLS_MAINDOC_FORM_NM") {
            scwin.gridList2ColInit();
            if (dts_List_1.getCellData(row, 'DISCLS_MAINDOC_FORM_CD') === "70766") {
                scwin.gridList2Col70766();
            } else if (dts_List_1.getCellData(row, 'DISCLS_MAINDOC_FORM_CD') === "70768") {
                scwin.gridList2Col70768();
            } else if (dts_List_1.getCellData(row, 'DISCLS_MAINDOC_FORM_CD') === "70795") {
                scwin.gridList2Col70795();
            } else if (dts_List_1.getCellData(row, 'DISCLS_MAINDOC_FORM_CD') === "70793") {
                scwin.gridList2Col70793();
            } else if (dts_List_1.getCellData(row, 'DISCLS_MAINDOC_FORM_CD') === "32101") {
                scwin.gridList2Col32101();
            } else if (dts_List_1.getCellData(row, 'DISCLS_MAINDOC_FORM_CD') === "32102") {
                scwin.gridList2Col32102();
            } else if (dts_List_1.getCellData(row, 'DISCLS_MAINDOC_FORM_CD') === "32103") {
                scwin.gridList2Col32103();
            } else if (dts_List_1.getCellData(row, 'DISCLS_MAINDOC_FORM_CD') === "32108") {
                scwin.gridList2Col32108();
            }
            scwin.readSyncInfo(row, colid);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10700.grd_List_1_OnClick" });
    }
};

