/**
 * @method
 * @name txb_ISUR_CD_3_onblur
 * @description txb_ISUR_CD_3 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_3_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_ISUR_CD_3.getValue() === "") {
            txb_COM_NM_3.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10700.txb_ISUR_CD_3_onblur" });
    }
};

