/**
 * @method
 * @name txb_ISUR_CD_3_onkeyup
 * @description txb_ISUR_CD_3 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_3_onkeyup = function() {
    try {
        if (txb_ISUR_CD_3.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10700.txb_ISUR_CD_3_onkeyup" });
    }
};

