/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10700.MxDataSet_com_isur_OnFilter" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name getDate
 * @description 익일영업일 가져옴
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getDate = async function() {
    const sbmOptions = {
        id : "sbm_dts_getDate",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_getDate=body.content",
        isProcessMsg : false
    };

