/**
 * @method
 * @name verifyBasPrc
 * @description 시장조치 내용 불러오기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.verifyBasPrc = async function() {
    // 1차 검토자가 다시 2차 검토를 할경우 체크
    if (dts_List_2.getCellData(1, 'FST_REVWR_EMP_NO') === js_id) {
        await $c.win.alert("1차 검토자와 2차 검토자는 같은 종목을 검토할수 없습니다.");
        return;
    }
    const isAlreadSubmitted = await scwin.isAlreadSubmittedCheck();
    if (isAlreadSubmitted === "N") {
        let res = window.confirm("기준[평가] 가격을 검토하시겠습니까?");
        if (res) {
            const retOK = scwin.verifyOk();
            if (retOK === "Y") {
                await $c.win.alert("기준[평가] 가격 일치");
                // 1차 검토 일치인 경우
                if (dts_List_2.getCellData(1, 'FST_REVWR_EMP_NM') === '') {
                    url += "&USR_ID=" + js_id;
                    url += "&APPL_NO=" + dts_List_2.getCellData(1, 'APPL_NO');
                    url += "&VERIFY_NUM=1";
                    const sbmOptions = {
                        id : "sbm_dts_parameter",
                        action : "/MktVerifSystem.do",
                        ref : "",
                        target : "dts_parameter=body.content",
                        isProcessMsg : false
                    };

                    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
                    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

                } else
                // 2차 검토 일치인 경우

                {
                    url += "&USR_ID=" + js_id;
                    url += "&APPL_NO=" + dts_List_2.getCellData(1, 'APPL_NO');
                    url += "&VERIFY_NUM=2";
                    const sbmOptions = {
                        id : "sbm_dts_parameter",
                        action : "/MktVerifSystem.do",
                        ref : "",
                        target : "dts_parameter=body.content",
                        isProcessMsg : false
                    };

                    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
                    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

                }
            } else {
                await $c.win.alert("기준[평가] 가격 불일치");
            }
        }
    } else {
        await $c.win.alert('해당 공시는 이미 처리되었습니다.');
    }
    await scwin.list();
};

