/**
 * @method
 * @name qryUrlBasPrcComp
 * @description qry Url Bas Prc Comp 처리
 * @param {*} pApplNo pApplNo
 * @param {String} pFormCd pFormCd
 * @returns {void}
 * @hidden N
 */
scwin.qryUrlBasPrcComp = function(pApplNo, pFormCd) {
    let url = "";
    if (pFormCd === "70766") {
        // 권리락
        url = "/listingCommon.do?SCREN_ID=" + "ULDSTF10700.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=ISU_BAS_PRC_REVW_PROC_COMP_LIST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.isubasprc.verif.basprc.comp." + pFormCd + "&{P}param01=" + pApplNo + "&{P}param02=" + dts_List_2.getCellData(1, 'BAS_PRC');
    } else if (pFormCd === "70768") {
        // 권배락
        url = "/listingCommon.do?SCREN_ID=" + "ULDSTF10700.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=ISU_BAS_PRC_REVW_PROC_COMP_LIST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.isubasprc.verif.basprc.comp." + pFormCd + "&{P}param01=" + pApplNo + "&{P}param02=" + dts_List_2.getCellData(1, 'BAS_PRC');
    } else if (pFormCd === "70795") {
        // 기준가격안내
        url = "/listingCommon.do?SCREN_ID=" + "ULDSTF10700.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=ISU_BAS_PRC_REVW_PROC_COMP_LIST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.isubasprc.verif.basprc.comp." + pFormCd + "&{P}param01=" + pApplNo + "&{P}param02=" + dts_List_2.getCellData(1, 'BAS_PRC');
    } else if (pFormCd === "70793") {
        // 매매개시일 기준가 산정 등에 관한 안내
        url = "/listingCommon.do?SCREN_ID=" + "ULDSTF10700.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=ISU_BAS_PRC_REVW_PROC_COMP_LIST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.isubasprc.verif.basprc.comp." + pFormCd + "&{P}param01=" + pApplNo + "&{P}param02=" + dts_List_2.getCellData(1, 'VALU_PRC') + "&{P}param03=" + dts_List_2.getCellData(1, 'HGST_ORD_PRC') + "&{P}param04=" + dts_List_2.getCellData(1, 'LWST_ORD_PRC');
    } else if (pFormCd === "32101") {
        // 코넥스권리락
        url = "/listingCommon.do?SCREN_ID=" + "ULDSTF10700.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=ISU_BAS_PRC_REVW_PROC_COMP_LIST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.isubasprc.verif.basprc.comp." + pFormCd + "&{P}param01=" + pApplNo + "&{P}param02=" + dts_List_2.getCellData(1, 'BAS_PRC');
    } else if (pFormCd === "32102") {
        // 코넥스권배락
        url = "/listingCommon.do?SCREN_ID=" + "ULDSTF10700.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=ISU_BAS_PRC_REVW_PROC_COMP_LIST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.isubasprc.verif.basprc.comp." + pFormCd + "&{P}param01=" + pApplNo + "&{P}param02=" + dts_List_2.getCellData(1, 'BAS_PRC');
    } else if (pFormCd === "32103") {
        // 코넥스기준가격안내
        url = "/listingCommon.do?SCREN_ID=" + "ULDSTF10700.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=ISU_BAS_PRC_REVW_PROC_COMP_LIST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.isubasprc.verif.basprc.comp." + pFormCd + "&{P}param01=" + pApplNo + "&{P}param02=" + dts_List_2.getCellData(1, 'BAS_PRC');
    } else if (pFormCd === "32108") {
        // 코넥스 매매개시일 기준가 산정 등에 관한 안내
        url = "/listingCommon.do?SCREN_ID=" + "ULDSTF10700.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=ISU_BAS_PRC_REVW_PROC_COMP_LIST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.isubasprc.verif.basprc.comp." + pFormCd + "&{P}param01=" + pApplNo + "&{P}param02=" + dts_List_2.getCellData(1, 'VALU_PRC') + "&{P}param03=" + dts_List_2.getCellData(1, 'HGST_ORD_PRC') + "&{P}param04=" + dts_List_2.getCellData(1, 'LWST_ORD_PRC');
    }
    return url;
};

