/**
 * @method
 * @name allCheck3
 * @description all Check3 처리
 * @returns {void}
 * @hidden N
 */
scwin.allCheck3 = function() {
    const checkArray = [chb_bzstat_20, chb_bzstat_22];
    if (chb_bzstat_99.checked === true) {
        for (let i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(1);
        }
    }
    if (chb_bzstat_99.checked === false) {
        for (let i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(0);
        }
    }
};

