 * @hidden N
 */
scwin.readSyncInfo = function(row, colid) {
    dts_List_2.DataID = encodeURI(scwin.qryUrlInfo(row, dts_List_1.getCellData(row, 'APPL_NO'), dts_List_1.getCellData(row, 'DISCLS_MAINDOC_FORM_CD')));
