};

/**
 * @method
 * @name getCondValue
 * @description get Cond Value 처리
 * @param {*} pCnt pCnt
 * @param {*} pVal pVal
 * @param {*} vCode vCode
 * @returns {void}
 * @hidden N
 */
scwin.getCondValue = function(pCnt, pVal, vCode) {
    if (pCnt > 0) {
        pVal += "," + vCode + "";
    } else {
        pVal = vCode;
    }
    return pVal;
};

/**
 * @method
 * @name getCondition3
 * @description get Condition3 처리
 * @returns {void}
 * @hidden N
 */
scwin.getCondition3 = function() {
    let vStatCnt = 0;
    let vStatCond = '';
    if (chb_bzstat_99.checked === true) {
        vStatCond = '';
        vStatCnt++;
    } else {
        if (chb_bzstat_20.checked === true) {
            vStatCond = scwin.getCondValue(vStatCnt, vStatCond, 'N');
            vStatCnt++;
        }
        if (chb_bzstat_22.checked === true) {
            vStatCond = scwin.getCondValue(vStatCnt, vStatCond, 'Y');
            vStatCnt++;
        }
    }
    return vStatCond;
};

